parameters.jsCode:
// The summary instruction is the one Mikko wrote (DM42-71), word for word,
// and the Telegram bot still uses it on its own. Around it the model is asked,
// in the same call, for the title in Finnish and an event's details (DM42-8),
// as JSON, so one call gives everything the newsletter needs. Improving the
// instruction is Mikko's part.
const SYSTEM = "You prepare articles for the member newsletter of a Finnish association. Answer with JSON only, no markdown fence, exactly this shape:\n{\"title\": \"...\", \"summary\": \"...\", \"event\": null}\n\ntitle: the article's title in Finnish. If the original title is already in Finnish, copy it unchanged. Otherwise translate it into short, natural Finnish that says the same thing and adds nothing.\n\nsummary: Tiivistä seuraava uutinen jäsenkirjeeseen kolmella lyhyellä suomenkielisellä lauseella. Kerro vain se mitä tekstissä lukee. Älä keksi mitään lisää.\n\nevent: null, unless the article announces an event people can attend or take part in, such as a conference, a webinar, a seminar, a training or a workshop. Then give:\n{\"starts\": \"YYYY-MM-DD\", \"ends\": \"YYYY-MM-DD\", \"time\": \"13-16\", \"place\": \"the city, or Verkko for an online event\", \"deadline\": \"YYYY-MM-DD\"}\nUse only what the text says, and null for anything it does not give. ends is only for an event of several days. When a date has no year, take the year from the publication date. deadline is the last day to sign up or to send a proposal.";

return { json: {
  task: 'summarise',
  item_id: $json.id,
  // an older summary being made again, see Pick queued
  refresh: $json.refresh === true,
  json: true,
  system_prompt: SYSTEM,
  user_text: `Title: ${$json.title}\nPublished: ${$json.published}\n\n${$json.raw_text}`,
} };

// The model answers with JSON: the title in Finnish, the summary, and an
// event's details. Only what passes the checks is kept: a date has to be a
// real date, and a missing one stays empty rather than guessed. With no
// summary at all the article is marked failed, or for an older summary being
// made again, the old one stays.
const r = $input.first().json;
const asked = $('One at a time').first().json;
const out = {
  item_id: asked.item_id, refresh: asked.refresh === true,
  provider: r.provider || '', model: r.model || '',
  summary: '', title: null, starts: null, ends: null, time: null, place: null, deadline: null,
  error: (r.error && (r.error.message || r.error)) || '',
};
const text = (value, max) => {
  const v = typeof value === 'string' ? value.replace(/\s+/g, ' ').trim() : '';
  return v && v.length <= max ? v : null;
};
const day = (value) => {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const d = new Date(`${value}T00:00:00Z`);
  const year = d.getUTCFullYear();
  return !isNaN(d) && d.toISOString().slice(0, 10) === value && year >= 2000 && year <= 2100 ? value : null;
};

if (!out.error && r.text) {
  let answer = null;
  try {
    answer = JSON.parse(String(r.text).trim().replace(/^```(json)?\s*/i, '').replace(/\s*```$/, ''));
  } catch (e) {
    answer = null;
  }
  if (answer && typeof answer === 'object') {
    out.summary = text(answer.summary, 3000) || '';
    out.title = text(answer.title, 300);
    const e = answer.event && typeof answer.event === 'object' ? answer.event : null;
    if (e) {
      out.starts = day(e.starts);
      out.ends = day(e.ends);
      if (out.ends && (!out.starts || out.ends <= out.starts)) out.ends = null;
      out.time = text(typeof e.time === 'string' ? e.time.replace(/-/g, '–') : null, 40);
      out.place = text(e.place, 120);
      out.deadline = day(e.deadline);
    }
    if (!out.summary) out.error = 'the model gave no summary';
  } else {
    out.error = r.truncated ? 'the answer was cut off before it ended' : 'the answer was not the JSON asked for';
  }
}
return [{ json: out }];

// A link an editor sent to the bot while the AI was down gets its summary
// here, and the bot promised to send it. Anything else just carries on.
// A failed message never stops the loop: the summary is saved either way.
const r = $json;
if (r.status === 'summarised' && r.telegram_user_id && !r.refresh) {
  const text = ($('Read answer').first().json.summary || '').trim();
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`,
      body: { chat_id: r.telegram_user_id, text: `Summary for: ${r.title}\n\n${text}`,
              disable_web_page_preview: true },
      json: true,
    });
  } catch (e) { /* nothing more to do */ }
}
return [{ json: r }];

// Ask the model server whether it is there before sending it up to 20
// articles. If it is down, stop here: the articles stay queued and the next
// run, 15 minutes later, tries again. Nothing is marked failed for an outage
// that was not the article's fault.
const rows = $input.all();
const cfg = rows[0].json;
if (cfg.llm_provider === 'ollama') {
  try {
    await this.helpers.httpRequest({ url: `${cfg.llm_base_url}/api/version`, timeout: 5000, json: true });
  } catch (e) {
    return [];
  }
}
return rows;
